}

local t = 0
local idx = 1
local lastCFrame = cam.CFrame

RunService.RenderStepped:Connect(function(dt)
    t = t + dt
    
    local maxTime = frames[#frames].Time
    if t > maxTime + 0.15 then
        -- Opsional: loop atau freeze
        -- t = 0  -- uncomment jika ingin loop
        -- idx = 1
        cam.CFrame = lastCFrame
        return
    end
    
    -- Cari segment yang benar (lebih aman dari skip)
    while idx < #frames and t >= frames[idx + 1].Time do
        idx = idx + 1
    end
    
    if idx >= #frames then
        cam.CFrame = lastCFrame
        return
    end
    
    local a = frames[idx]
    local b = frames[idx + 1]
    
    if not (a and b) then return end
    
    local duration = b.Time - a.Time
    if duration <= 0 then duration = 0.016 end  -- proteksi
    
    local alpha = (t - a.Time) / duration
    alpha = math.clamp(alpha, 0, 1)
    
    -- Interpolate dengan sedikit smoothing ekstra
    local pos  = a.Pos:Lerp(b.Pos, alpha)
    local vel  = a.Vel:Lerp(b.Vel, alpha)
    local move = a.Move:Lerp(b.Move, alpha)
    local fov  = a.FOV + (b.FOV - a.FOV) * alpha
    local cf   = a.CFrame:Lerp(b.CFrame, alpha)
    
    lastCFrame = cf
    
    cam.CFrame = cf
    cam.FieldOfView = fov
    
    -- Karakter menghadap kamera (flat)
    local look = Vector3.new(cf.LookVector.X, 0, cf.LookVector.Z).Unit
    if look.Magnitude > 0.01 then
        hrp.CFrame = CFrame.new(pos, pos + look * 10)
    end
    
    hum:Move(move, true)
    hrp.AssemblyLinearVelocity = vel * 0.98  -- sedikit damping biar lebih smooth
    
    -- Jump handling
    if a.Jump or b.Jump then
        hum.Jump = (alpha < 0.6 and a.Jump) or (alpha >= 0.4 and b.Jump)
    end
end)
